class Strategy(bt.Strategy):
    params = dict(
        exit_target=0.05,
        entry_target=0.01,
    )

    def __init__(self):
        self.dataclose = self.datas[0].close
        self.datahigh = self.datas[0].high
        self.datalow = self.datas[0].low
        self.dataopen = self.datas[0].open
        self.volume = self.datas[0].volume

    def next(self):
        if self.dataclose[0] >= self.dataclose[-1] * (1 + self.entry_target):
            self.buy()
        elif self.dataclose[0] <= self.dataclose[-1] * (1 - self.exit_target):
            self.sell()

