class Strategy(bt.Strategy):
    params = (
        ('rsi_period', 14),
        ('rsi_upper', 70),
        ('rsi_lower', 30),
        ('buy_signal', 20),
        ('sell_signal', 80),
    )

    def __init__(self):
        self.rsi = bt.indicators.RSI_SMA(self.data.close, period=self.params.rsi_period)
        self.data_close = self.datas[0].close

    def next(self):
        cash_to_invest = self.broker.getcash()
        total_value = self.broker.getvalue()
        num_shares = int(total_value / self.data_close)
        share_price = self.data_close[0]

        rsi_value = self.rsi[0]

        if rsi_value <= self.params.rsi_lower:
            if num_shares > self.params.buy_signal:
                self.sell(exactsize=(num_shares - self.params.buy_signal) * share_price)
            if cash_to_invest > num_shares * share_price * self.params.buy_signal:
                self.buy(exactsize=self.params.buy_signal * share_price)

        elif rsi_value >= self.params.rsi_upper:
            if num_shares > self.params.sell_signal:
                self.sell(exactsize=(num_shares - self.params.sell_signal) * share_price)

