class Strategy(bt.Strategy):
    def __init__(self):
        self.sma = bt.indicators.SimpleMovingAverage(self.data.close, period=20)
        self.bb = bt.indicators.BollingerBands(self.data.close)
        self.countdown = 0

    def next(self):
        if self.data.close[0] > self.sma[0] and self.data.close[0] > self.bb.top[0]:
            self.close()
            if self.countdown <= 0:
                self.buy()
                self.countdown = 20
        elif self.data.close[0] < self.sma[0] and self.data.close[0] < self.bb.bottom[0]:
            self.close()
            if self.countdown <= 0:
                self.sell()
                self.countdown = 20
        else:
            self.close()

        if self.countdown > 0:
            self.countdown -= 1

