class Strategy(bt.Strategy):
    def __init__(self):
        self.dataclose = self.datas[0].close
        self.datahigh = self.datas[0].high
        self.pc = self.datas[0].close.get(1, 0)
        self.trend = 0

    def next(self):
        if self.pc == 0:
            self.trend = 0
        else:
            if self.dataclose[0] > self.datahigh[-1] and self.dataclose[0] > self.pc:
                self.trend = 1
            elif self.dataclose[0] < self.pc:
                self.trend = -1
            else:
                self.trend = 0

        if self.trend == 1 and not self.position:
            self.buy()
        elif self.trend == -1 and self.position:
            self.close()

class Strategy(bt.Strategy):
