        self.sma_cross = bt.indicators.CrossOver(self.datas[0].close, self.sma)

    def next(self):
        if not self.position and self.buy_signal[0] and self.sma_cross[0] > 0:
            self.buy()
        elif self.position and (not self.buy_signal[0] or self.sma_cross[0] < 0):
            self.sell()
