class Strategy(bt.Strategy):
    params = (
        ('buy_stop_distance', 0.01),
        ('sell_stop_distance', -0.01),
    )

    def __init__(self):
        self.sma = bt.indicators.MovingAverageSimple(self.data.close, period=50)
        self.order = None

    def next(self):
        if self.order:
            return

        if not self.position:
            if self.data.close[0] > self.sma[0] + self.buy_stop_distance:
                self.order = self.buy()
            elif self.data.close[0] < self.sma[0] + self.sell_stop_distance:
                self.order = self.sell()
        else:
            if self.data.close[0] < self.sma[0] - self.sell_stop_distance:
                self.order = self.sell()
            elif self.data.close[0] > self.sma[0] - self.buy_stop_distance:
                self.order = self.sell(target=self.position.size // 2)
            else:
                self.order = self.close()

    def notify_order(self, order):
        if order.status in [order.Completed]:
            if order.isbuy():
                pass
            elif order.issell():
                pass
        self.order = None

