class Strategy(bt.Strategy):
    params = (
        ('rsi_period', 14),
        ('rsi_upper', 70),
        ('rsi_lower', 30),
        ('order_percentage', 0.95),
    )

    def __init__(self):
        self.rsi = bt.indicators.RSI_SMA(self.data.close, period=self.params.rsi_period)
        self.order = None

    def next(self):
        if self.order:
            return

        if self.data.close[0] > self.rsi[0] > self.params.rsi_lower:
            if not self.position:
                self.order = self.order_target_percent(target=self.params.order_percentage)
        elif self.data.close[0] < self.rsi[0] < self.params.rsi_upper:
            if self.position:
                self.order = self.sell(size=self.position.size)

