        self.sma = bt.indicators.SimpleMovingAverage(self.data.close, period=20)
        self.bbands = bt.indicators.BollingerBands(self.data.close, period=20, devfactor=2)
        self.long = None
        self.short = None

    def next(self):
        if not self.position:
            if self.data.close[0] < self.bbands.lb[0] and self.sma[0] > self.sma[-1]:
                self.long = self.order_target_percent(data=self.data, target=1.0)
            elif self.data.close[0] > self.bbands.mid[0] and self.sma[0] < self.sma[-1]:
                self.short = self.order_target_percent(data=self.data, target=0.0)
        else:
            if self.position.size > 0:
                if self.data.close[0] > self.bbands.mid[0]:
                    self.sell(data=self.data)
            else:
                if self.data.close[0] < self.bbands.lb[0]:
                    self.buy(data=self.data)

