class Strategy(bt.Strategy):
    params = (('stoploss', -0.05), ('target', 0.10))

    def __init__(self):
        self.sma = bt.indicators.SimpleMovingAverage(self.data.close, period=20)

    def next(self):
        position = self.getposition(self.data).size
        if not position:
            if self.data.close[0] > self.sma[0]:
                self.buy()
            else:
                self.close()
        else:
            if self.data.close[0] / position.price < self.params.stoploss:
                self.close()
            elif self.data.close[0] / position.price > 1 + self.params.target:
                self.close()
            else:
                self.order_target_percent(target=self.params.target)

