        self.sma = bt.indicators.SimpleMovingAverage(self.data.close, period=50)

    def next(self):
        if not self.position:
            if self.data.close[0] > self.sma[0]:
                self.buy()
        else:
            if self.data.close[0] < self.sma[0]:
                self.sell()

class Strategy(bt.Strategy):
    def __init__(self):
        self.sma = bt.indicators.MovingAverageSimple(self.data.close, period=50)
        self.sma2 = bt.indicators.MovingAverageSimple(self.data.close, period=200)

    def next(self):
        if self.data.close[0] > self.sma2[0] and self.data.close[-1] <= self.sma2[-1]:
            self.buy()
        elif self.data.close[0] < self.sma2[0] and self.data.close[-1] >= self.sma2[-1]:
            self.sell()

class Strategy(bt.Strategy):
    params = (
        ('ma_period', 40),
    )

    def __init__(self):
        self.sma = bt.indicators.SimpleMovingAverage(self.data.close, period=self.params.ma_period)

    def next(self):
        if self.data.close[0] > self.sma[0] and self.position.size == 0:
            self.buy(size=100)
        elif self.data.close[0] < self.sma[0] and self.position.size > 0:
            self.sell(size=100)

class Strategy(bt.Strategy):
    def __init__(self):
        self.sma = bt.indicators.SimpleMovingAverage(self.data.close, period=50)

    def next(self):
        if self.data.close > self.sma:
            self.order_target_percent(self.data, 1.0)
        else:
            self.order_target_percent(self.data, 0.0)

class Strategy(bt.Strategy):
    def __init__(self):
        self.sma = bt.indicators.SMA(self.data.close, period=50)
        self.bb = bt.indicators.BollingerBands(self.data.close, period=21, devfactor=2.0)
        self.crossover = bt.indicators.CrossOver(self.data.close, self.sma)
        self.count = 0

    def next(self):
        if not self.position:
            if self.crossover > 0:
                if self.data.close[0] < self.bb.lines.bot1[0]:
                    self.buy()
        else:
            if self.crossover < 0:
                self.sell()
            elif self.data.close[0] > self.bb.lines.top1[0]:
                self.sell()

