class Strategy(bt.Strategy):
    params = (
        ('maperiod', 21),
        ('smaperiod', 12),
    )

    def __init__(self):
        self.dataclose = self.datas[0].close
        self.sma_short = bt.indicators.SimpleMovingAverage(self.dataclose, period=self.params.smaperiod)
        self.sma_long = bt.indicators.SimpleMovingAverage(self.dataclose, period=self.params.maperiod)

    def next(self):
        if self.sma_short[0] > self.sma_long[0] and self.sma_short[-1] <= self.sma_long[-1] and self.position == 0:
            self.buy()
        elif self.sma_short[0] < self.sma_long[0] and self.sma_short[-1] >= self.sma_long[-1] and self.position != 0:
            self.sell()

class Strategy(bt.Strategy):
    def __init__(self):
        self.sma_short = bt.indicators.SimpleMovingAverage(self.data.close, period=20)
        self.sma_long = bt.indicators.SimpleMovingAverage(self.data.close, period=50)
        self.order = None

    def next(self):
        if self.order:
            return

        if self.sma_short[0] > self.sma_long[0] and self.sma_short[-1] <= self.sma_long[-1]:
            self.order = self.buy()
        elif self.sma_short[0] < self.sma_long[0] and self.sma_short[-1] >= self.sma_long[-1]:
            self.order = self.sell()

