class Strategy(bt.Strategy):
    params = (
        ('exitbars', 12),
        ('stake', 1)
    )

    def __init__(self):
        self.sma = bt.indicators.MovingAverageSimple(self.data.close, period=15)
        self.order = None

    def next(self):
        if not self.position:
            if self.data.close[0] > self.sma[0]:
                self.order = self.buy()
        else:
            if (self.curpos * self.data.close[0]) - (self.position.size * self.data.close[0]) > self.position.size * self.price[0] * self.params.exitbars:
                self.order = self.sell()

class Strategy(bt.Strategy):
    def __init__(self):
        self.data_close = self.datas[0].close
        self.order = None

    def next(self):
        if not self.position:
            if self.data_close[0] > self.data_close[-1]:
                if self.data_close[0] > self.data_close[-2]:
                    self.order = self.buy()
        else:
            if self.data_close[0] < self.data_close[-1]:
                if self.data_close[0] < self.data_close[-2]:
