class Strategy(bt.Strategy):
    def __init__(self):
        self.sma = bt.indicators.SimpleMovingAverage(self.data, period=20)
        self.bb = bt.indicators.BollingerBands(self.data, period=20)

    def next(self):
        if self.data.close[0] > self.bb.top[0]:
            self.sell()
        elif self.data.close[0] < self.bb.bot[0]:
            self.buy()
        elif self.sma[0] > self.data.close[0]:
            self.sell()
        elif self.sma[0] < self.data.close[0]:
            self.buy()
        else:
            self.close()

class Strategy(bt.Strategy):
