        self.sma = bt.indicators.SimpleMovingAverage(self.data, period=50)
        selfrsi = bt.indicators.RSI_SMA(self.data, period=14)

    def next(self):
        if self.data.close > self.sma and self.rsi < 30:
            self.buy()
        elif self.data.close < self.sma and self.rsi > 70:
            self.sell()
        elif self.data.close > self.sma and self.rsi > 30:
            self.close()
        elif self.data.close < self.sma and self.rsi < 70:
            self.close()

class Strategy(bt.Strategy):
    def __init__(self):
        self.sma = bt.indicators.SimpleMovingAverage(self.data.close, period=50)
        self.bb = bt.indicators.BollingerBands(self.data.close, period=20)
        self.rsi = bt.indicators.RSI_SMA(self.data.close, period=14)
        self.count = 0

    def next(self):
        if self.count % 3 == 0:
            if self.data.close < self.bb.lowerband:
                self.buy()
            elif self.data.close > self.bb.upperband:
                self.sell()
        elif self.count % 3 == 1:
            if self.rsi < 30:
                self.buy()
            elif self.rsi > 70:
                self.sell()
        self.count += 1

