class Strategy(bt.Strategy):
    params = (
        ('atr_period', 14),
        ('atr_multi', 2.0),
        ('rsi_period', 14),
        ('rsi_overbought', 70),
        ('rsi_oversold', 30),
    )

    def __init__(self):
        self.atr = bt.indicators.ATR(self.data, period=self.p.atr_period)
        self.rsi = bt.indicators.RSI_SMA(self.data, period=self.p.rsi_period)
        self.entry_price = 0.0
        self.position_size = 0.0

    def next(self):
        if self.data.close[0] > self.data.close[-1]:  # Price is higher than previous close
            if (self.data.close[0] - self.data.close[-1]) > self.atr[0] * self.p.atr_multi:
                if self.rsi[0] < self.p.rsi_oversold and self.position_size == 0:
                    self.position_size = 1.0 / self.data.high[0] * self.atr[0] * self.p.atr_multi
                    self.event driven('buy', price=self.data.high[0] * (1 + self position_size / self.atr[0] * self.p.atr_multi))
        elif self.data.close[0] < self.data.close[-1]:  # Price is lower than previous close
            if (self.data.close[-1] - self.data.close[0]) > self.atr[0] * self.p.atr_multi:
                if self.rsi[0] > self.p.rsi_overbought and self.position_size > 0:
                    self.event driven('sell', price=self.data.low[0] * (1 - self position_size / self.atr[0] * self.p.atr_multi))

    def event driven(self, order_type, price):
        if order_type == 'buy':
            self.buy(size=self.position_size, price=price)
        elif order_type == 'sell':
            self.sell(size=self.position_size, price=price)

