        elif self.data.close[0] < self.bb[0] and self.data.close[1] >= self.bb[1]:
            self.sell()
        elif self.data.close[0] > self.sma[0] and self.data.close[1] <= self.sma[1]:
            self.buy()
        elif self.data.close[0] < self.sma[0] and self.data.close[1] >= self.sma[1]:
