class Strategy(bt.Strategy):
    params = (
        ('fast_period', 10),
        ('slow_period', 30),
        ('thresh', 0.01),
    )

    def __init__(self):
        self.fast_EMA = bt.indicators.EMA(self.data.close, period=self.params.fast_period)
        self.slow_EMA = bt.indicators.EMA(self.data.close, period=self.params.slow_period)
        self.crossover = bt.indicators.CrossOver(self.fast_EMA, self.slow_EMA)

    def next(self):
        if not self.position:
            if self.crossover > 0:
                self.order_target_percent(target=1.0)
        elif self.crossover < 0:
            self.close()

        position_size = self.position.size
        if position_size > 0:
            if self.data.close[0] - self.data.close[-1] > self.params.thresh * self.data.close[-1]:
                self.order_target_percent(target=1.0)
            elif self.data.close[0] - self.data.close[-1] < -self.params.thresh * self.data.close[-1]:
                self.close()

