                self.close()

class Strategy(bt.Strategy):
    params = (('rsi_period', 14), ('rsi_overbought', 70), ('rsi_oversold', 30), ('rsi_target', 80), ('rsi_stop', 20))

    def __init__(self):
        self.rsi = bt.indicators.RSI_SMA(self.data.close, period=self.p.rsi_period)
        self.sma = bt.indicators.SMA(self.data.close, period=20)

    def next(self):
        if self.rsi[0] > self.p.rsi_overbought and self.rsi[-1] <= self.p.rsi_overbought:
            self.close()
            if not self.is_long:
                self.buy()
        elif self.rsi[0] < self.p.rsi_oversold and self.rsi[-1] >= self.p.rsi_oversold:
            self.close()
            if not self.is_short:
                self.sell()
        elif self.data.close[0] > self.sma[0]:
            self.close()
            if not self.is_long:
                self.buy()
        elif self.data.close[0] < self.sma[0]:
            self.close()
            if not self.is_short:
                self.sell()

