class Strategy(bt.Strategy):
    params = (
        ('atr_period', 14),
        ('atr_multiplier', 1.4),
    )

    def __init__(self):
        atr = bt.indicators.ATR(self.data, period=self.params.atr_period)
        upper_band = self.data.high + self.params.atr_multiplier * atr
        lower_band = self.data.low - self.params.atr_multiplier * atr

        self.order = None

    def next(self):
        if self.order:
            if self.order.status in [bt.Order.Submitted, bt.Order.Accepted, bt.Order.Partial]:
                return

        if not self.position:
            if self.data.close[0] > self.lower_band[0]:
                self.order_target_percent(self.data, 1.0)
        else:
            if self.data.close[0] < self.upper_band[0]:
                self.order_target_percent(self.data, 0.0)

