class Strategy(bt.Strategy):
    params = (
        ('short_period', 30),
        ('long_period', 100),
    )

    def __init__(self):
        self.short_ma = bt.indicators.SimpleMovingAverage(self.data.close, period=self.params.short_period)
        self.long_ma = bt.indicators.SimpleMovingAverage(self.data.close, period=self.params.long_period)
        self.order = None

    def next(self):
        if self.order:
            return

        if self.short_ma[0] > self.long_ma[0] and self.short_ma[-1] <= self.long_ma[-1]:
            self.order = self.order_target_percent(target={self.data: 1.0})
        elif self.short_ma[0] < self.long_ma[0] and self.short_ma[-1] >= self.long_ma[-1]:
            self.order = self.order_target_percent(target={self.data: 0.0})

