class Strategy(bt.Strategy):
    params = (('buy_threshold', 0.02), ('sell_threshold', -0.01))

    def __init__(self):
        self.data_close = self.datas[0].close
        self.data_high = self.datas[0].high
        self.data_low = self.datas[0].low

    def next(self):
        close = self.data_close[0]
        high = self.data_high[0]
        low = self.data_low[0]

        if close > high * (1 + self.buy_threshold):
            self.order_target_percent(self.datas[0], 1.0)
        elif close < low * (1 + self.sell_threshold):
            self.order_target_percent(self.datas[0], 0.0)

