class Strategy(bt.Strategy):
    params = (
        ('per_entry', 1.0),
        ('per_loss', 0.5),
        ('max_stocks', 5),
    )

    def __init__(self):
        self.order = None
        self.data0 = self.datas[0]
        self.valid_orders = []

    def next(self):
        if self.order:
            return

        if len(self.valid_orders) >= self.params.max_stocks:
            return

        if self.data0.close[0] > self.data0.close[-1]:
            self.order = self.order_target_percent(self.data0, self.params.per_entry / 100)
            self.valid_orders.append(self.order)
        elif self.data0.close[0] < self.data0.close[-1]:
            self.order = self.order_target_percent(self.data0, -self.params.per_loss / 100)
            self.valid_orders.append(self.order)

    def notify_order(self, order):
        if order.status in [order.Submitted, order.Accepted]:
            return

        if order.status in [order.Completed]:
            if order.isbuy():
                self.valid_orders.remove(order)
            elif order.issell():
                self.valid_orders.remove(order)

