class Strategy(bt.Strategy):
    params = (
        ('atr_period', 14),
        ('atr_multiplier', 2.0),
    )

    def __init__(self):
        self.atr = bt.indicators.ATR(self.data, period=self.params.atr_period)
        self.upper_band = self.data.high + (self.atr * self.params.atr_multiplier)
        self.lower_band = self.data.low - (self.atr * self.params.atr_multiplier)

    def next(self):
        if self.data.close[0] > self.upper_band[0]:
            self.sell()
        elif self.data.close[0] < self.lower_band[0]:
            self.buy()
        else:
            self.close()

