class Strategy(bt.Strategy):
    params = (
        ('short_window', 20),
        ('long_window', 50),
        ('pos_limit', 0.05),
    )

    def __init__(self):
        self.dataclose = self.data.close
        self.shortw = self.p.short_window
        self.short = bt.indicators.MovingAverageSimple(
            self.dataclose, period=self.shortw, plotfalse
        )
        self.longw = self.p.long_window
        self.long = bt.indicators.MovingAverageSimple(
            self.dataclose, period=self.longw, plotfalse
        )
        self.poslim = self.p.pos_limit
        self.order_id = None

    def next(self):
        short, long = self.short[0], self.long[0]
        pos = self.position.size / abs(self.position.size) if self.position else 0
        if not self.position and short < long:
            self.order_target_percent(exectype=bt.Order.Market, target=pos=self.poslim)
        elif self.position and pos >= self.poslim and short >= long:
            self.close()
        elif not self.position and pos < self.poslim and short >= long:
            self.close()

        if self.order_id and self.order.datetime.datetime() == self.data.datetime.datetime():
            self.order_id = None

class Strategy(bt.Strategy):
    params = dict(sma_period=20, ema_period=50, short_ratio=0.5)

    def __init__(self):
        self.dataclose = self.datas[0].close
        self.datasize = len(self.dataclose)
        self.sma = bt.ind.SMA(period=self.p.sma_period)
        self.ema = bt.ind.EMA(period=self.p.ema_period)

    def next(self):
        if not self.position:
            if self.sma > 0 and self.ema > 0 and self.sma > self.ema:
                if self.sma - self.ema > self.dataclose * self.p.short_ratio:
                    self.buy()
        elif self posiiton and (self.sma < self.ema or self.sma - self.ema < self.dataclose * self.p.short_ratio):
            self.sell()

class Strategy(bt.Strategy):
    def __init__(self):
        self.dataclose = self.data.close
        self.fast_ma = bt.ind.MovingAverage Simple(self.dataclose, period=20)
        selfslow_ma = bt.ind.MovingAverage Simple(self.dataclose, period=50)
        self.crossover = bt.ind.CrossOver(self.fast_ma, self.slow_ma)

    def next(self):
        if self.crossover > 0 and self.position.size == 0:
            self.buy()
        elif self.crossover < 0 and self.position.size > 0:
            self.close()
            self.order_target_percent(target=0.0)

