            if not self.order:
                self.sell()

class Strategy(bt.Strategy):
    params = (('bb_period', 20), ('bb_dev_std', 2.0), ('rsi_period', 14), ('rsi_buy_level', 30), ('rsi_sell_level', 70), ('buy_percent', 0.8), ('sell_percent', 0.2))

    def __init__(self):
        self.dataclose = self.datas[0].close
        self.boll = bt.indicators.BollingerBands(self.dataclose, period=self.params.bb_period, devstd=self.params.bb_dev_std)
        self.rsi = bt.indicators.RSI(self.dataclose, period=self.params.rsi_period)
        self.order = None

    def next_start(self):
        if not self.order:
            return False
        else:
            return True

    def next(self):
        if not self.position:
            if self.dataclose > self.boll.lines.top and self.rsi.lines.rsi < self.params.rsi_buy_level:
                self.buy(size=int(self.broker.size*0.5))
                self.close(size=int(self.broker.size*0.5), percent=self.params.buy_percent)
            elif self.dataclose < self.boll.lines.bot and self.rsi.lines.rsi > self.params.rsi_sell_level:
                self.sell(size=int(self.broker.size*0.75))
        else:
            if self.dataclose >= self.boll.lines.top and self.rsi lines.rsi > self.params.rsi_sell_level:
                self.sell(percent=self.params.sell_percent) 
            elif self.dataclose <= self.boll.lines.bot and self.rsi.lines.rsi < self.params.rsi_buy_level:
                self.buy(percent=self.params.buy_percent)

