class Strategy(bt.Strategy):
    params = (('short_window', 20), ('long_window', 50), ('emphasize_long', True), ('starting_cash', 10000.0), ('cash_percentage', 0.01))

    def __init__(self):
        self.short_window = self.p.short_window
        self.long_window = self.p.long_window
        self.emphasize_long = self.p.emphasize_long
        self.cash_percentage = self.p.cash_percentage
        self.starting_cash = self.p.starting_cash
        self.short_mavg = self.xr(self.data.low, self.short_window)
        self.long_mavg = self.xr(self.data.high, self.long_window)
        self.delta = self.nr(self.short_mavg - self.long_mavg)

    def next(self):
        if self.emphasize_long:
            if self.delta > 0 and self.adjclose > self.long_mavg:
                if self.adjclose < self.long_mavg:
                    self.close_target = self.long_mavg + (self.adjclose - self.long_mavg) * self.cash_percentage
                    self.order_target_percent(target=self.close_target / self.long_mavg, size=self.starting_cash / self.long_mavg)
                else:
                    self.sell()
            else:
                self.close()
        else:
            if self.delta > 0 and self.adjclose > self.short_mavg:
                if self.adjclose <= self.short_mavg:
                    self.close_target = self.short_mavg + (self.adjclose - self.short_mavg) * self.cash_percentage
                    self.order_target_percent(target=self.close_target / self.short_mavg, size=self.starting_cash / self.short_mavg)
                else:
                    self.sell()
            else:
                self.close()

