class Strategy(bt.Strategy):
    params = (('short_win', 20), ('long_win', 50),
              ('short_mnb', 2), ('long_mnb', 3),
              ('risk_allocation', 0.05))

    def __init__(self):
        self.short_win = self.p.short_win
        self.long_win = self.p.long_win
        self.short_mnb = self.p.short_mnb
        self.long_mnb = self.p.long_mnb
        self.risk_allocation = self.p.risk_allocation

        self.data_close = self.datas[0].close
        self.short_emas = bt.indicators.ExponentialMovingAverage(
            self.data_close, period=self.short_win)
        self.long_emas = bt.indicators.ExponentialMovingAverage(
            self.data_close, period=self.long_win)

    def next(self):
        if not self.position:
            if self.short_emas > self.long_emas:
                pos_allocation = (self.pos.value or 0) * self.risk_allocation / self.broker.getvalue()
                pos_size = self.data_close * pos_allocation / self.short_emas
                if pos_size > 0:
                    self.buy()
        else:
            if self.short_emas > self.long_emas:
                pos_allocation = (self.pos.value or 0) * self.risk_allocation / self.broker.getvalue()
                pos_size = self.data_close * pos_allocation / self.short_emas
                if pos_size > 0:
                    self.close(exectype=bt.PositionClosure)
                    self.buy()

