class Strategy(bt.Strategy):
    params = (('buy_ma_short', 20), ('buy_ma_long', 50), ('sell_ma_short', 20), ('sell_ma_long', 50), ('cash_percent', 0.05), ('r_multiplier', 2))

    def __init__(self):
        self.dataclose = self.datas[0].close
        self.buy_signal = bt.indicators.MovingAverageSimple(self.dataclose, period=self.params.buy_ma_short)
        self.buy_threshold = bt.indicators.MovingAverageSimple(self.dataclose, period=self.params.buy_ma_long)
        self.sell_signal = bt.indicators.MovingAverageSimple(self.dataclose, period=self.params.sell_ma_short)
        self.sell_threshold = bt.indicators.MovingAverageSimple(self.dataclose, period=self.params.sell_ma_long)

    def next(self):
        if self.buy_signal > self.buy_threshold and self.position.size == 0:
            self.buy(exectype=bt.Position.Side.LONG, size=self.order_target_percent())

        if (self.sell_threshold > self.sell_signal * self.params.r_multiplier and self.sell_threshold > self.dataclose) or (self.position.size > 0 and self.updatecashpercent()):
            self.close()
            self.sell(exectype=bt.Position.Side.LONG, size=self.order_target_percent())

    def updatecashpercent(self):
        if self.data.get_last_price() > 0:
            return self.position.size * self.params.cash_percent < self.broker.get_cash() / self.data.get_last_price()

class Strategy(bt.Strategy):
    params = (('buy_signal_shift', 2), ('sell_signal_shift', 3), ('position_size', 0.5))

    def __init__(self):
        self.dataclose = self.datas[0].close

        self.close_ma = bt.indicators.SMA(self.dataclose, period=20)
        self.buy_signal = bt.indicators.Stochastic(self.dataclose, period=14, overbought=70, oversold=30, format='%f')
        self.sell_signal = bt.indicators.Stochastic(self.dataclose, period=14, overbought=30, oversold=70, format='%f')

        self.shifted_buy_signal = self.buy_signal.lines.shift(param=self.params.buy_signal_shift)
        self.shifted_sell_signal = self.sell_signal.lines.shift(param=self.params.sell_signal_shift)

    def next(self):
        cash = self.broker.get_cash()
        value = self.dataclose[0] * cash
        pos_size = self.position.size if self.position else 0

        if self.position:
            if self.close_ma[0] > self.close_ma[-1] and self.shifted_sell_signal[0] < self.shifted_sell_signal[-1]:
                self.close(size=pos_size)
        else:
            if self.shifted_buy_signal[0] < self.shifted_buy_signal[-1] and self.shifted_sell_signal[0] > self.sell_signal.lines.series.lines[-2]:
                self.buy(size=int(value*self.params.position_size/cash))

class Strategy(bt.Strategy):
    params = (('fast_ma_len', 20), ('slow_ma_len', 50), ('rare_price', 5.0), ('buy_percent', 0.7), ('cash_ratio', 0.5), ('loss_ratio', 0.5))

    def __init__(self):
        self.fast_ma = bt.ind.SMA(period=self.params.fast_ma_len)
        self.slow_ma = bt.ind.SMA(period=self.params.slow_ma_len)
        self.roc = (self.close - self.close rollover(992)) / (self.close rollover(992))
        self.long_entered = bt Indicators.Entries/

    def next(self):
        if not self.position:
            if self.roc > 0 and self.fast_ma > self.slow_ma:
                if self.slow_ma - self.fast_ma > self.params.rare_price:
                    pct = self.order_target_percent(target_value=self.cash * self.params.buy_percent)
                    self.buy(exectype = bt.Order.SkipExisting,
                             price = self.fast_ma,
                             size =pct)
        else:
            if self.fast_ma - self.slow_ma < 0:
                self.close(solicited = True)

class Strategy(bt.Strategy):
    params = (('fast_window', 20), ('slow_window', 50), ('short_threshold', 10))

    def __init__(self):
        self.data_fast = self.data.close()
        self.data_slow = self.data.close().rolling(window=self.p.fast_window).mean()
        self.data_trend = self.data_slow.rolling(window=self.p.slow_window).mean()
        self.order_target_percent = self.broker.get_target_percent(self.data)

    def next(self):
        if self.data_fast > self.data_trend and self.data_trend > self.data_trend[-1] + self.p.short_threshold:
            self.buy(exectype=bt.Order.Exit, size=100)
        elif self.data_fast < self.data_trend and self.data_trend < self.data_trend[-1] - self.p.short_threshold:
            self.sell(exectype=bt.Order.Exit, size=100)

class Strategy(bt.Strategy):
    params = (('fast_ma_len', 10), ('slow_ma_len', 50), ('ema_len', 20), ('stop_loss_pcnt', 0.02), ('take_profit_pcnt', 0.05))

    def __init__(self):
        self.addindicator(bt.indicators.MovingAverage, name='fast_ma', length=self.params.fast_ma_len, plot=False)
        self.addindicator(bt.indicators.MovingAverage, name='slow_ma', length=self.params.slow_ma_len, plot=False)
        self.addindicator(bt.indicators.MovingAverage, name='ema', length=self.params.ema_len, plot=False)

    def next(self):
        fast_ma = self.fast_ma
        slow_ma = self.slow_ma
        ema = self.ema

        if self.pos:
            if fast_ma > ema and fast_ma > slow_ma and fast_ma.data.close > fast_ma.data.close[0]:
                self.close()
        else:
            if fast_ma < ema and fast_ma < slow_ma and fast_ma.data.close < fast_ma.data.close[0]:
                self.buy()
                self.order_target_percent(target=self.params.take_profit_pcnt)

            if ema.data.close < fast_ma.data.close and ema.data.close < ema.data.close[0]:
                self.sell(stop_exect=None, stop_price=emama.data.close[0] * (1 + self.params.stop_loss_pcnt))
                self.order_target_percent(target=-self.params.take_profit_pcnt)

