class Strategy(bt.Strategy):
    params = (('fast_ma_period', 20),
              ('slow_ma_period', 50),
              ('pos_ratio', 0.5))

    def __init__(self):
        self.fast_ma = bt.ind%SMA(self.data, period=self.p.fast_ma_period)
        self.slow_ma = bt.ind%SMA(self.data, period=self.p.slow_ma_period)

    def next(self):
        if self.fast_ma() > self.slow_ma():
            target_size = self.pos.size * self.p.pos_ratio
            target_units = target_size / self.data.close()
            if target_units > 0 and not self.position:
                self.order_target_percent(target=target_units)

            elif self.pos.size * self.data.close() * (1 + self.p.pos_ratio) < self.data.close * self.pos.size:
                self.order_target_percent(target=target_units)

            elif self.pos.size * self.data.close() * (1 + self.p.pos_ratio) > self.data.close * 2 * self.pos.size:
                self.close()

