    def fast_ma_cross_record(self):
        return self.fast_ma_cross() > 0

    def fast_ma_cross_unrecord(self):
        return self.fast_ma_cross() < 0

    def checkposition(self):
        if not self.fast_ma_cross_record():
            return False
        if self.fast_ma_cross_unrecord() and self.close_bid() * 1.00100 >= self.close_ask():
            return False
        if self.position and self.size * self.close_bid() < self.broker.getvalue() * self.p.risk_percent:
            return False
        return True

    def checkexittlpclidapaped(self):
        if self.fast_ma_cross_unrecord() and self.close_bid() * 1.00100 >= self.close_ask():
            self.close()
        if self.position and self.size * self.close_bid() < self.broker.getvalue() * self.p.risk_percent:
            self.close()
        if not self.checkposition():
            self.close()

class Strategy(bt.Strategy):
    params = (('fast_ma_period', 10), ('slow_ma_period', 20), ('buy_threshold', 0.05), ('sell_threshold', 0.95), ('risk_factor', 1.0))

    def __init__(self):
        self.fast_ma = bt.indicators.SMA(period=self.params.fast_ma_period)
        self.slow_ma = bt.indicators.SMA(period=self.params.slow_ma_period)
        self.dataclose = self.data.close

    def next(self):
        if not self.position:
            if self.fast_ma > self.slow_ma + (self.slow_ma * self.params.buy_threshold):
                self.buy(exectype=bt.Order SessoImmediate, price=self.dataclose[0])
        else:
            ma_above_crossover = self.fast_ma > self.dataclose
            ma_below_crossover = self.fast_ma < self.dataclose
            self.close(exectype=bt.Order.Close,closeday=datetime.timedelta(minutes=0),price=self.dataclose[0],taulfill=False)
            # Momentum condition to open new position in cash
            if self.risk_factor!= 1 and (self.slow_ma -ma_above_crossover) <= (self.dataclose * self.risk_factor):
                self.close()

            if ma_above_crossover:
                self.close()
                self.sell(exectype=bt.Order SessoImmediate, price=self.dataclose[0])
            if ma_below_crossover and self.slow_ma < self.dataclose:
                self.close()
                self.buy(exectype=bt.Order SessoImmediate, price=self.dataclose[0])

