        self.bollash = bt.indicators.SMA(self.dataclose, period=boll_length)
        self.boll = bt.indicators.SMA(self.dataclose, period=boll_length)
        self.bbhigh = bt.indicators.SMA(self.dataclose, period=boll_length) + 2 * bt.indicators.StdDev(self.dataclose, period=boll_length)
        self.bblow = bt.indicators.SMA(self.dataclose, period=boll_length) - 2 * bt.indicators.StdDev(self.dataclose, period=boll_length)
        create_autobase_strategy_logic()

    def next(self):
        if self.dataclose[0] < self.bblow[0] and self.boll[0] < self.bollash[0]:
            self.buy()

