            self.sell()


def create_autobase_strategy_logic():
    if self.position and self.dataclose[0] > self.bollash[0]:
        self.close()
    if self.position and self.dataclose[0] < self.bollash[0]:
        self.sell()
    elif not self.position and self.dataclose[0] > self.bblow[0]:
        self.buy()

