        self.dataclose = self.datas[0].close
        self.fastmovavg = bt.ind.ExponentialMovingAverage(self.dataclose, period=self.params.period)
        self.slowmovavg = bt.ind.ExponentialMovingAverage(self.dataclose, period=50)
        self.signal = bt.ind.CrossOver(self.fastmovavg, self.slowmovavg)
        self.stop_loss_percent = 0.05
        self.take_profit_percent = 0.50

    def next(self):
        if self.signal > 0 and self.fastmovavg > self.slowmovavg and self.dataclose > self.fastmovavg.lines[-1]:
            self.order_target_percent(target=self.params.cash * 0.90)
        elif self.signal < 0 and self.fastmovavg < self.slowmovavg and self.dataclose < self.fastmovavg.lines[-1]:
            self.close()
        elif self.signal > 0:
            highest_price = max(self.datas[0].close.get(size=len(self.datas[0].close))) - self.stop_loss_percent * max(self.datas[0].close.get(size=self.params.period))
            if self.dataclose < highest_price:
              self.close()
            highest_price_sell = max(self.datas[0].close.get(size=self.params.period)) - self.take_profit_percent * max(self.datas[0].close.get(size=self.params.period))
            if self.dataclose > highest_price_sell:
                self.close()

