        self.sellind = self.ema_slow < self.ema_fast
        self.shortinterval = (self.buyind and (self.dataclose / self.ema_fast.price) > self.p.shortgest)
        self.longinterval = (self.sellind and (self.ema_slow.price / self.dataclose) > self.p.longest)

    def next(self):
        if self.shortinterval:
            if self.position:
                self.close()
            self.buy(exectype=bt.Order.Market, quantity=self.broker.getvalue() * self.p.shortgest)
