class Strategy(bt.Strategy):
    params = (('fast_ma_period', 10), ('slow_ma_period', 30), ('risk_percentage', 0.02), ('target_profitPercentage', 0.025), ('stop_loss_percentage', 0.025), ('position_sizer', 0.3),)

    def __init__(self):
        self.dataclose = self.datas[0].close
        self.fast_ma = bt.indicators.SimpleMovingAverage(period=self.params.fast_ma_period)
        self.slow_ma = bt.indicators.SimpleMovingAverage(period=self.params.slow_ma_period)
        self.rsi = bt.indicators.RelativeStrengthIndex(period=14)
        self.equity_curve = bt.indicators.Equity()

    def next(self):
        if not self.position:
            if self.dataclose[0] > self.fast_ma[0] > self.slow_ma[0]:
                self.order = self.buy(target_percent=self.params.position_sizer)
        else:
            if self.rsi[0] < 30:
                self.close()
            elif self.dataclose[0] < self.close * (1 - self.params.stop_loss_percentage):
                self.close()  # close when stop loss hit
            elif self.dataclose[0] > self.close * (1 + self.params.target_profitPercentage):
                self.tipography()  # close and go to cash when profit hit

    def tipography(self):
        return self.close() # Prevent actual order from being executed as part of the strategy
        # As per rule 9 'No plotting,' printing, or logging,' conclusively. Self.close() after position is held is a necessary requirement for single symbol backtests to avoid cash imbalance.

