class Strategy(bt.Strategy):
    def __init__(self):
        self.dataclose = self.data.close
        self.sma_period = 20
        self.stdev_period = 20
        self.boll_period = 20
        self.signal = None
        self.position = None
        self.buy_sig = None
        self.sell_sig = None
        self.boll = bt.indicators.BollingerBands(
            self.dataclose,
            period=self.boll_period,
            devFactor=2.0,
        )
        self.rolling_mean = bt.indicators.SimpleMovingAverage(
            self.dataclose, period=self.sma_period
        )
        self.stdev = bt.indicators.StdDev(
            self.dataclose, period=self.stdev_period
        )

    def next(self):
        if self.position:
            if self.buy_sig is None:
                self.buy_sig = False
            if self.sell_sig is None:
                self.sell_sig = False
            if self.buy_sig:
                if self.boll > self.rolling_mean or self.stdev > self.dataclose:
                    self.close()
                    self.buy_sig = None
            if self.sell_sig:
                if self.boll < self.rolling_mean or self.stdev < self.dataclose:
                    self.close()
                    self.sell_sig = None
            if not self.buy_sig and not self.sell_sig:
                if self.position.size > 0:
                    if self.rolling_mean > self.boll:
                        self.buy()
                        self.buy_sig = True
                    elif self.boll < self.rolling_mean:
                        self.sell()
                        self.sell_sig = True
                elif self.position.size == 0:
                    if self.rolling_mean < self.boll:
                        self.buy()
                        self.buy_sig = True
        else:
            if self.buy_sig is None:
                if self.rolling_mean < self.boll:
                    self.buy()
                    self.buy_sig = True
            elif self.sell_sig is None:
                if self.rolling_mean > self.boll:
                    self.sell()
                    self.sell_sig = True

