class Strategy(bt.Strategy):
    params = (('short_window', 50), ('long_window', 200), ('buy_threshold', 0.05),
              ('sell_threshold', 0.05))

    def __init__(self):
        self.data_close = self.data
        self.addbb()
        self.arrays = self.bb + self.data_close

    def addbb(self):
        self.sma_short, self.sma_long = bt.indicators.SMA(
            self.arrays, period=self.params.short_window), bt.indicators.SMA(self.arrays, period=self.params.long_window)

    def next(self):
        if not self.position:

            if self.sma_short[-1] > self.params.buy_threshold * self.sma_long[-1]:
                self.buy(exectype=bt.Position-sizingvalue)

            elif self.params.sell_threshold < self.sma_short[-1]/self.sma_long[-1]:
                self.sell(exectype=bt.Position.sizingvalue)

        elif self.position:

            if self.sma_short[-1] > self.params.buy_threshold * self.sma_long[-1]:
                self.close()

            elif self.params.sell_threshold <  self.sma_short[-1]/ self.sma_long[-1]:
                self.close()

