class Strategy(bt.Strategy):
    params = (
        ('short_window', 20),
        ('long_window', 50),
        ('std_window', 14),
    )

    def __init__(self):
        self.short_ma = bt.indicators.SMA(period=self.p.short_window)
        self.long_ma = bt.indicators.SMA(period=self.p.long_window)
        self.std_dev = bt.indicators.StdDev(self.data.close, period=self.p.std_window)
        self.upper_band = self.data.close + (2 * self.std_dev)
        self.lower_band = self.data.close - (2 * self.std_dev)

    def next(self):
        if self.data.close > self.upper_band:
            if self.position.size == 0:
                self.order_target_percent(target=1.0, exectype=bt.Order.SELL)
        elif self.data.close < self.lower_band:
            if self.position.size == 0:
                self.order_target_percent(target=1.0, exectype=bt.Order.BUY)

class Strategy(bt.Strategy):
    params = (('short_window', 10), ('long_window', 25), ('buy_threshold', 0.02), ('cash_volatility', 0.05), ('stock_volatility', 0.20),
              ('buy_ratio', 0.4), ('sell_ratio', 0.2), ('close_ratio', 0), ('rebal detalial', 10),)

    def __init__(self):
        self.short_window = self.p.short_window
        self.long_window = self.p.long_window

        self.rsi = bt.indicators.RSI(self.data, period=self.long_window, mesh=False, plot=False)
        selfDatos = self.datas[0]

        self.moveToBuy = bt.indicators.SimpleMovingAverage(self.rsi, period=self.short_window) > self.rsi

        self.moveToSell = (self.rsi >= 70) | selfDatos.close * self.moveToBuy

    def next(self):

        if self.moveToBuy and self.rsi < 80:
            self.order_target_percent(self.datas[0], target=self.p.buy_ratio)

        if self.moveToSell or self.rsi > 80:
            self.order_target_percent(self.datas[0], target=self.p.sell_ratio)

