        self.short_signal = bt.ind.CrossOver(self.fast_ma, self.slow_ma, 1)
        self.long_signal = bt.ind.CrossOver(self.fast_ma, self.slow_ma, -1)

    def next(self):
        if not self.position and self.short_signal > 0 and self.data.close > self.data.close[-self.p.short_period] and self.data.close[-self.p.long_period] < self.data.close[-self.p.long_period-1]:
            self.buy()
        elif self.position and self.long_signal < 0 and self.data.close < self.data.close[-self.p.short_period] and self.data.close[-self.p.long_period] > self.data.close[-self.p.long_period-1]:
            self.close()

class Strategy(bt.Strategy):
    params = (
        ('short_window', 50),
        ('long_window', 200),
        ('buy_percent', 0.05),
        ('cash_percent', 0.03),
        ('nominal_target', 0.01),
    )

    def __init__(self):
        self.dataclose = self.data.close
        self.short = bt.talib.MA(self.dataclose, period=self.params.short_window)
        self.long = bt.talib.MA(self.dataclose, period=self.params.long_window)

    def next(self):
        if self.dataclose[0] < self.short[0] and self.dataclose[0] > self.short[-10]:
            if self.position.size == 0 or self.order.status in ['Submitted', 'PartiallyDone']:
                self.sell()
        if self.dataclose[0] > self.long[0] and self.dataclose[0] < self.long[-10]:
            if self.position.size == 0 or self.order.status in ['Submitted', 'PartiallyDone']:
                self.close()
                self.buy(size=int(self.broker.getvalue() * self.params.buy_percent / self.dataclose[0]))
        if self.order:
            if self.order.getstatus() in ['Submitted', 'PartiallyDone'] and self.cash > self.pos.size * self.dataclose[0] * self.params.nominal_target:
                self.order_target_percent(target=self.params.nominal_target, exectype=bt.Order.Market)
            elif self.order.getstatus() == 'Filled' and self.pos.size > 0:
                if self.dataclose[0] < self.dataclose[-1] and self.pos.size * self.dataclose[0] * self.params.cash_percent < self.cash:
                    self.close(size=int(self.pos.size * self.params.nominal_target / self.params.cash_percent / self.dataclose[0]))
                else:
                    self.order_target_percent(target=self.params.nominal_target, exectype=bt.Order.Market)

