        self.fastema = self.p.fastema_period
        self.slowema = self.p.slowema_period
        self.signal = self.p.signal_period

        self.dfema = bt.ind.MovingAverageSimple(
            plot=False, periods=self.fastema
        )
        self.sfema = bt.ind.MovingAverageSimple(
            plot=False, periods=self.slowema
        )
        self.signal = bt.ind.MovingAverageSimple(
            plot=False, periods=self.signal, plot=False
        )

        self.crossover = bt.ind.CrossOver(
            self.dfema,
            self.sfema,
            plot=False
        )

    def next(self):

        if self.crossover > 0:

            if self.position.size == 0:
                size = self.broker.getcash() / (self.dfema[0] + self.dfema[-1]) / (self.dfema[-1] - self.dfema[0])
                self.order_target_percent(target=size)

            else:
                self.close()

        elif self.crossover < 0:
            if self.position.size > 0:
                self.close()

