    params = (('fast', 16), ('slow', 48), ('buy_sign', 1), ('sell_sign', -1))

    def __init__(self):
        super().__init__()
        self.fast = bt.ind.SMA(period=self.p.fast)
        self.slow = bt.ind.SMA(period=self.p.slow)
        self.adv = bt.ind.SMA(period=max(16, self.p.fast))
        self.diff = self.fast - self.slow

        self.long_screener = (self.diff * self.adv)

    def next(self):
        if self.long_screener > self.p.buy_sign:
            self.buy()
            self.close()
        elif self.long_screener < self.p.sell_sign:
            self.sell()

