class Strategy(bt.Strategy):
    params = (
        ('short_window', 20),
        ('long_window', 50),
        ('sma_percent', 0.05),
    )

    def __init__(self):
        self.dataClose = self.data.close
        self.short_win = self.p.short_window
        self.long_win = self.p.long_window
        self.sma_percent = self.p.sma_percent
        self.addindicator(self.dataClose, 'short_sma', 'simple_moving_average', period=self.short_win)
        self.addindicator(self.dataClose, 'long_sma', 'simple_moving_average', period=self.long_win)
        self.indicator = self.short_sma.copy().minus(self.long_sma.copy())
        self.crossover = self.indicator.copy()
        self.simple_moving_average = self.short_sma.copy()

    def addindicator(self, datum, varname, kind, period=None, selfreference=None):
        setattr(self.data, f'{varname}', bt.ind.BollingerBands(
            self.data, period=period, dev=self.p.sma_percent, noplot=True, selfreference=selfreference
            ) )

    def next(self):
        if self.pervalue.index[0] > self.now.index[0]:
            return False

        if self.short_sma.currentvalue > self.long_sma.currentvalue:
            if self.crossover >= 0:
                risky = self.order_target_percent(targetpercent=0.99) # 99%
                self.close(risky, excepproc=self.p.sma_percent, selfreference=True)
        elif self.short_sma.currentvalue < self.long_sma.currentvalue:
            if self.crossover < 0:
                cautious = self.order_target_percent(targetpercent=0.01) # 1%
                self.close(cautious, excepproc=self.p.sma_percent, selfreference=True)
        return True

