class Strategy(bt.Strategy):
    params = (('fast_ma_period', 26), ('slow_ma_period', 52), ('stop_loss_pct', 0.05), ('risk_reward_ratio', 2.5))

    def __init__(self):
        fast_ma = bt.indicators.SMA(period=self.p.fast_ma_period)
        slow_ma = bt.indicators.SMA(period=self.p.slow_ma_period)
        self.signum = fast_ma - slow_ma
        self order = self.order

    def next(self):
        if self.signum > 0:
            if not self.position:
                self.order_target_percent(target=self.size * self.p.stop_loss_pct)
            else:
                if self.pos.size / self.pos.price > self.size * self.p.stop_loss_pct:
                    self.close()
                else:
                    if self.position.size / self.position.price * self.p.risk_reward_ratio < self.position.buy_price + self.position.buy_comm * -1:
                        self.order_target_percent(target=self.size * self.p.stop_loss_pct)

        if self.signum < 0:
            if not self.position:
                self.long()
            else:
                if self.pos.size / self.pos.price > self.size * self.p.stop_loss_pct:
                    self.close()
                else:
                    if self.position.size / self.position.price * self.p.risk_reward_ratio < self.position.buy_price + self.position.buy_comm * -1:
                        self.order_target_percent(target=self.size * self.p.stop_loss_pct)

    def long(self):
        target_share_no = self.size / (self.position.buy_price + self.position.buy_comm * -1) * self.p.risk_reward_ratio
        self.buy(exectype=bt.Order.Limit, price=target_share_no)

    def close(self):
        self.sell(exectype=bt.Order.Limit, price=self.position.price + self.p.stop_loss_pct)

class Strategy(bt.Strategy):
    def __init__(self):
        # Fast EMA with 20 periods
        self.ema20 = bt.indicators.EMA(
            period=20, plotname="NKE EMA 20"
        )

        # Fast EMA with 50 periods
        self.ema50 = bt.indicators.EMA(
            period=50, plotname="NKE EMA 50"
        )

    def next(self):
        # Check if 200 EMA has crossed above 50 EMA
        if self.ema20.lines[0] > self.ema50.lines[0]:
            # Check if close price crossed above 50 EMA
            if self.data.close > self.ema50.lines[0]:
                # Long position
                self.buy()

        # Check if 200 EMA has crossed below 50 EMA
        elif self.ema20.lines[0] < self.ema50.lines[0]:
            # Check if close price crossed below 200 EMA
            if self.data.close < self.ema20.lines[0]:
                # Close long position
                self.close()

