class Strategy(bt.Strategy):
    params = (('pfast', 5), ('pslow', 12), ('period', 26), ('stddev', 2), ('cash', 100000))
    buy_signals = None
    stop_losses = None
    long_position = False
    short_position = False

    def __init__(self):
        self.dataclose = self.datas[0].close
        self.bear_cross = bt.indicators.CCI(period=self.params.period)
        self.bull_cross = bt.indicators.CCI(period=self.params.period)
        self.speed = bt.indicators.EMA(period=self.params.pfast)
        self.slow = bt.indicators.EMA(period=self.params.pslow)
        self.short_procedure = bt.indicators.CCI(period=self.params.pfast)
        self.stop_below = 0
        self.stop_above = 0
        self.sma_50 = bt.indicators.SMA(period=50)
        self.sma_200 = bt.indicators.SMA(period=200)

    def next(self):

        if not self.position:
            if self.dataclose > self.slow and self.dataclose > self.speed and self.dataclose < self.sma_200 and self.sma_50 > self.sma_200:
                self.buy()

        if self.position:
            if (self.short_procedure < - self.params.stddev and self.long_position == False):
                self.long_position = True

            if (self.short_procedure >  self.params.stddev and self.long_position == True):
                self.long_position = False
                self.close()

            if (self.short_procedure >  self.params.stddev and self.short_position == False and self.sma_50 < self.sma_200):
                self.short_position = True
                self.order_target_percent(target=1.0)
                self.stop_below = self.dataclose - (self.dataclose * 0.05)

            if (self.short_procedure < - self.params.stddev and self.short_position == True):
                self.short_position = False
                self.close()

            if (self.long_position == True):
                if (self.dataclose < self.stop_below or self.short_position == True):
                    self.close()
                    self.long_position = False

            if (self.short_position == True):
                if (self.dataclose > self.stop_above or self.long_position == True):
                    self.close()
                    self.short_position = False

class Strategy(bt.Strategy):
    params = (('rvi_fast', 13), ('rvi_slow', 21), ('macd_fast', 12), ('macd_slow', 26), ('macd_signal', 9), ('stop_pct', 0.1), ('cash_percent', 50))

    def __init__(self):
        self.addindicator(bt.indicators.RVI, self.data, period=self.p.rvi_fast, name='rvi_fast')
        self.addindicator(bt.indicators.RVI, self.data, period=self.p.rvi_slow, name='rvi_slow')
        self.addindicator(bt.indicators.Macd, self.data, fast=self.p.macd_fast, slow=self.p.macd_slow, signal=self.p.macd_signal, name='macd')

    def next(self):
        # Get the current values
        rvi_fast = self.rvi_fastclose *
        rvi_slow = self.rvifastclose *
        price = self.data.close *
        macd = self.macd - self.macdsignal

        # Trigger a buy order when RVI crosses up and the line within range of 10%
        if (rvi_fast > rvi_slow) and (rvi_fast > (0.9 * rvi_slow)):
            if (price > (1 - self.p.stop_pct) * self.data_.close[-1]):
                self.buy()

        # Trigger a sell order when RVI crosses down and the line within range of 10%
        if (rvi_fast < rvi_slow) and (rvi_fast < (0.9 * rvi_slow)):
            if (price < (1 + self.p.stop_pct) * self.data_.close[-1]):
                self.sell()

        # Trigger a buy order when MACD < 0 and the line within range of 10%
        if (macd < 0) and ((macd / macd[-2]) > (0.9)):
            if (price > (1 - self.p.stop_pct) * self.data_.close[-1]):
                self.buy()

        # Trigger a sell order when MACD > 0 and the line within range of 10%
        if (macd > 0) and ((macd / macd[-2]) > (0.9)):
            if (price < (1 + self.p.stop_pct) * self.data_.close[-1]):
                self.sell()

