class Strategy(bt.Strategy):
    params = (('ma_fast', 20),
              ('ma_slow', 50),
              ('entry_percentage', 0.025),
              ('exit_percentage', 0.025))

    def __init__(self):
        self.dataclose = self.data
        self.datafastma = self.data.close(-self.params.ma_fast)
        self.dataslowma = self.data.close(-self.params.ma_slow)

    def next(self):

        if len(self) >= self.params.ma_fast and len(self) >= self.params.ma_slow:

            if self.datafastma > self.datalastfastma and self.datalastfastma > self.datalastslowestma:
                self.buy(size=int(self.broker.getvalue() * self.params.entry_percentage / self.data.close[-1]))

            elif self.datafastma < self.datalastfastma and self.datalastfastma < self.datalastslowestma:
                self.sell(size=int(self.broker.getvalue() * self.params.entry_percentage / self.data.close[-1]))

            elif (self.datalastfastma < self.datafastma) and (self.datafastma <= self.datalastslowestma):
                if self.position:
                    self.close()

            elif (self.datalastfastma > self.datafastma) and (self.datafastma >= self.datalastslowestma):
                self.buy_size = int(self.broker.getvalue() * self.params.exit_percentage / self.data.close[-1])
                self.purchase = self.getposition().size
                if self.purchase >= self.buy_size and self.position:
                    self.close(size=self.getposition().size - self.buy_size)

            self.datalastfastma = self.datafastma
            self.datalastslowestma = self.dataslowma

