    def next(self):
        if self.short_signal > 0 and not self.in_position:
            self.order_target_percent(target=1)
            self.order_price = self.data.close

        elif self.long_signal > 0 and not self.in_position:
            self.order_target_percent(target=1)
            self.order_price = self.data.close

        elif self.in_position:
            if self.position.size < 0:
                if self.position.price * (1 + self.cash_ratio) < self.data.close:
                    self.close()
            else:
                if self.position.price * (1 - self.cash_ratio) > self.data.close:
                    self.close()

    def notify_fundamental_newdata(self, data):
        pass

