            return
        if not order.status.done():
            return
        to_buy = self.order.input.size - self.order.value
        to_sell = self.order.value - self.order.input.size
        if to_buy > 0:
            self.order_target_percent()
            if self.order.total_limit unloaded == None:
                buycash = self.order.total_limit unloaded
            else:
                buycash = 0
            if buycash + self.order.size > self.order.sizecash:
                self.close()
                self.order_target_percent()

        elif to_sell > 0:
            if self.posSugarlen is none:
