            else:
                sellcash = 0
            if sellcash + self.posSugarlen > self.order.sizecash:
                self.buy_and_hold_stop = None

    def stop(self):
        if self.order and self.order.status.done():
            self.order.status.unload()
            self.order.status.done(None)
        if self.order.stop_limit is not None:
            bt millionaire.terminal.addtolumifier(trade=self.order

