class Strategy(bt.Strategy):
    params = (('ema_period', 14), ('sma_period', 50), ('entry_price_percent', 0.02), ('exit_price_percent', 0.05), ('crossover_threshold', 0.95))

    def __init__(self):
        self.dataclose = self.datas[0].close
        self.sma = bt.indicators.SMA(period=self.p.sma_period)
        self.ema = bt.indicators.EMA(price=self.dataclose,
                                     period=self.p.ema_period)
        self.crossover = bt.indicators.CrossOver(self.sma, self.ema)
        self.entry_order = None
        self.entry_possibility = False

    def next(self):
        if self.entry_order is None or not self.entry_order:IsActive():
            if self.crossover > self.p.crossover_threshold and not self.entry_possibility:
                self.entry_order = self.buy(size=self.p.entry_price_percent * self.broker.getvalue())
                self.entry_possibility = True
        else:
            sma_val = self.sma.lines.sma
            ema_val = self.ema.lines.ema
            close_val = self.dataclose[0]
            if self.crossover < -1 and self.entry_possibility:
                if close_val > ema_val * self.p.exit_price_percent:
                    self.close()
                    self.entry_order = None
                    self.entry_possibility = False
                elif close_val < sma_val:
                    self.sell(size=self.p.entry_price_percent * self.broker.getvalue() + 0.0001)
                    self.entry_order = None
                    self.entry_possibility = False

class Strategy(bt.Strategy):
    params = (('short_window', 20),
              ('long_window', 50),
              ('risk', 0.02),  # 2%
              ('short_percent', 0.8),
              ('long_percent', 0.2))

    def __init__(self):
        self.data_close = self.data.close
        self.short_window = self.params.short_window
        self.long_window = self.params.long_window
        self.risk = self.params.risk
        self.short Percent = self.params.short_percent
        self.long Percent = self.params.long_percent

        self.data_sma_short = self.short_window_shift
        self.data_sma_long = self.long_window_shift

    def long_window_shift(self):
        return bt.indicators.MovingAverageSimple(
            self.data_close,
            period=self.long_window
        )

    def short_window_shift(self):
        return bt.indicators.MovingAverageSimple(
            self.data_close,
            period=self.short_window
        )

    def next(self):
        if not self.position:
            momentum = self.data_sma_long - self.data_sma_short
            if momentum > 2 * self.data_sma_short * self.risk:
                self.order_target_percent(target=self.short_percent)
        else:
            momentum = self.data_sma_long - self.data_sma_short
            if momentum <= 0:
                self.close()
            elif self.position.size <= 1:
                if momentum < -self.risk * self.data_sma_short:
                    self.order_target_percent(target=self.long_percent)

