            self.log(f'SentryBuy{self.params.fast_win_period}-{self.params.slow_win_period}')
            self.order = self.close(exectype=bt.Order.Stop, price=self.data.close*1.043, opeartype=bt.Order.Sell) 

    def stop(self):
        super().stop() 

    def onstop(self):
        super().onstop()

