class Strategy(bt.Strategy):
    def __init__(self):
        # Indicators
        self.data_close = self.datas[0].close
        self.fast_ma = bt.indicators.SMA(period=20)
        self.slow_ma = bt.indicators.SMA(period=50)
        self.crossover = bt.indicators.Crossover(self.fast_ma, self.slow_ma)
        self.rsi = bt.indicators.RSI(self.data_close, period=14)
        self.boll = bt.indicators.BollingerBands(period=20, movingstd=2)

        # Initialize flags for buy and sell signals
        self.buy_signal = False
        self.sell_signal = False

    def next(self):
        if not self.position:
            # Buy condition: long entry when RSI drops below 30 and Crossover triggers a fast SMA crossing the slow SMA
            # Also, confirm the long entry criteria with the Buy and Sell flags
            if not self.buy_signal and self.rsi < 30 and self.crossover.tickflag == Crossover.LONG and not self.sell_signal:
                self.buy_signal = True
                self.buy()
        else:
            # Sell condition: long exit when RSI reaches 75 or the Sell flag is triggered
            if self.buy_signal and self.rsi >= 75 or self.sell_signal:
                self.close()
                self.buy_signal = False
                self.sell_signal = False
             # buy at the start price

    # calling self.close whenever you want to close the strategy with no value loss
    def notify_user(self):
        return self.close()

