class Strategy(bt.Strategy):
    params = (('fast_ma_period', 20), ('slow_ma_period', 50), ('atr_short_window', 20))

    def __init__(self):
        self.closeprice = self.data.close
        self.fast_ma = bt.ind.SMA(period=self.params.fast_ma_period)
        self.slow_ma = bt.ind.SMA(period=self.params.slow_ma_period)
        self.atr = bt.ind.ATR(self.params.atr_short_window)
        self.stop_price = self.closeprice.copy()
        self.threshold = self.closeprice.copy()

    def next(self):
        self.fast_ma.plot()
        self.stop_price[:] = max(min(self.closeprice * 0.95, self.stop_price[-1]*0.95), min(self.closeprice * 1.05, self.stop_price[-1]*1.05))
        self.threshold[:] = self.closeprice * 0.97
        if not self.position:
            if self.fast_ma > self.slow_ma:
                self.buy()
                self.close(self.stop_price)
        else:
            if self.closeprice < self.threshold or self.closeprice > self.stop_price:
                self.close(self.stop_price)

