    params = (('p_price_window', 20), ('p_stop_loss_pct', 0.02), ('p_take_profit_pct', 0.05), ('p_risk_reward_ratio', 2.5))

    def __init__(self):
        self.dataclose = self.data.close
        self.datahigh = self.data.high
        self.datalow = self.data.low
        self.c_moving_avg = bt.indicators.MovingAverageSimple(self.dataclose, period=self.params.p_price_window)
        self.c_stop_loss = self.data.close * (1 - self.params.p_stop_loss_pct)
        self.c_take_profit = self.data.close * (1 + self.params.p_take_profit_pct)
        self.c_risk_reward_target = self.data.close * (self.params.p_risk_reward_ratio * self.params.p_take_profit_pct + self.params.p_stop_loss_pct)

    def next(self):
        current_position = self.position.size
        if current_position:
            if self.data.close > self.c_take_profit.data0:
                self.close(target=self.order_target_percent(base=self.data.close))
            elif self.data.close < self.c_stop_loss.data0:
                self.close(target=self.order_target_percent(base=self.data.close))
        else:
            if self.data.close > self.c_take_profit.data0 and self.data.close > self.c_risk_reward_target.data0:
                self.buy(exectype=bt.Order.StopLimit, price=self.c_risk_reward_target.data0, target=self.order_target_percent(base=self.data.close))
            elif self.data.close < self.c_stop_loss.data0 and self.data.close < self.c_risk_reward_target.data0:
                self.sell(exectype=bt.Order.StopLimit, price=self.c_risk_reward_target.data0, target=self.order_target_percent(base=self.data.close))

