class Strategy(bt.Strategy):
    params = {
        'short_window': 20,  # short moving average window
        'long_window': 50  # long moving average window
    }

    def __init__(self):
        self.data_close = self.data
        self.short_ma = bt.ind.MovingAverageSimple(period=self.p.short_window, plotfalse)
        self.long_ma = bt.ind.MovingAverageSimple(period=self.p.long_window, plotfalse)
        self.stop_loss = self.broker.getvalue() * 0.05
        self.position_l = None
        self.equity_l = []
        self.stopLoss = None

    def next(self):
        if self.position:
            if self.position.size < 0 and (self.short_ma > self.long_ma):
                self.close()
            elif self.position.size > 0 and (self.short_ma < self.long_ma):
                self.close()
            else:
                pos_size = self.broker.getvalue() * 0.95
                if self.position.size < 0:
                    pos_size = -pos_size
                self.close(size=pos_size)

                self.order_target_percent(target=pos_size / self.broker.getvalue())

                self.stopLoss = self.broker.getvalue() * 0.05
                self.order_target_percent(target=self.stopLoss)

        else:
            if not self.equity_l or self.broker.getvalue() / self.equity_l[-1] > 1.05:
                if self.broker.getvalue() >= pos_size := self.broker.getvalue() * 0.95:
                    self.buy(size=pos_size)
            elif self.broker.getvalue() / self.equity_l[-1] < 0.95 and self.stopLoss is None:
                pos_size = self.broker.getvalue() * 0.05
                if self.broker.getvalue() >= pos_size * -1:
                    self.sell(size=pos_size * -1)
                    self.stopLoss = pos_size * -1
                self.order_target_percent(target=self.stopLoss)

            self.equity_l.append(self.broker.getvalue())

