        self.dataclose = self.datas[0].close
        self.datafast_ma = self.p.fast_ma_period
        self.datalong_ma = self.p.maperiod
        self.statslow_ma = self.p.slow_ma_period
        self.buylogic = self.dataclose() > self.shortest_ma() and self.shortest_ma() > self.mid_ma() and self.stock_overbought() == False
        self.selllogic = self.dataclose() < self.shortest_ma() and self.shortest_ma() < self.mid_ma() and self.stock_overbought() == True

        self.shortest_ma = self.pfast_smooth = bt.ind.MA(self.dataclose, period=self.datafast_ma, type=bt.ind.SMA)
        self.mid_ma = self.plong_smooth = bt.ind.MA(self.dataclose, period=self.datalong_ma, type=bt.ind.SMA)
        self.statslow_ma = self.pslow_smooth = bt.ind.MA(self.dataclose, period=self.statslow_ma, type=bt.ind.SMA)

    def stock_overbought(self):
        return self.plong_smooth > self.pslow_smooth

    def next(self):
        if self.buylogic:
            self.buy()
        elif self.selllogic:
            self.sell()

        if self.get_position():
            self.close()

