                self.close()

    def next_close(self):
        if self.position:
            position_percentage = self.position.size / self.initial_capital
            if self.auto_re_balance and (self.buy_profit / self.initial_capital > self.buy_profit_disposal or position_percentage < 0.5):
                self.order_target_percent(target=0.5)
            elif (self.dataclose - self.position.price) / self.position.price > self.buy_profit_disposal:
                self.sell()
            elif (self.position.price - self.dataclose) / self.position.price > self.stoploss_disposal:
                self.close()

    def next(self):
        self.next_open()
        self.next_close()

    def notify_fund(self):
        self.initial_capital = self.broker.getvalue()

    def notify_trade(self, ty, price, qty):
        if ty == 'long':
            self.buy_profit = (price * qty) - self.position.price * self.position.size
        else:
            self.buy_profit = 0

        if ty == 'long':
            self.stoploss_disposal = ((self.position.price - self.dataclose) / self.position.price)
        else:
            self.stoploss_disposal = 0

    def stop(self):
        self.order_target_percent(target=0.5)

