class Strategy(bt.Strategy):
    params = (('fast_ma', 10), ('slow_ma', 30), ('ratio', 0.02))

    def __init__(self):
        self.fast_ma = bt.ind.SimpleMovingAverage(period=self.params.fast_ma)
        self.slow_ma = bt.ind.SimpleMovingAverage(period=self.params.slow_ma)
        self.ratio = self.params.ratio

    def next(self):
        pos = self.position.size
        near_limit = self.broker.getvalue() * self.ratio
        if pos and self.fast_ma.line <= self.slow_ma.line:
            if pos > near_limit:
                self.close()
        elif not pos and self.fast_ma.line >= self.slow_ma.line:
            if self.broker.getvalue() > near_limit:
                self.buy()

