class Strategy(bt.Strategy):
    params = (('fast_ma_window', 10),
              ('slow_ma_window', 20),
              ('risk_free_return', 0),  # if negative returns
              ('risk_free_percent', 0))  # percentage of equity per trade

    def __init__(self):
        self.fast_ma = bt.ind.SMA(period=self.params.fast_ma_window)
        self.slow_ma = bt.ind.SMA(period=self.params.slow_ma_window)
        self.stake = self.broker.get_cash() / self.size(**self.params)

    def next(self):
        if not self.position:
            if self.fast_ma > self.slow_ma:
                self getOrder(self.stake * self.params.risk_free_return)
            else:
                self getOrder(-self.stake * self.params.risk_free_return)
        else:
            if self.fast_ma < self.slow_ma:
                self.close()
                self getOrder(-self.stake * self.params.risk_free_return)

    def size(self, risk_free_percent=None, risk_free_return=None):
        if risk_free_return is None:
            risk_free_return = self.params.risk_free_return
        if risk_free_percent is None:
            risk_free_percent = self.params.risk_free_percent

        return self.stake * risk_free_percent if risk_free_percent!= 0 else risk_free_return

    def getOrder(self, size):
        if size < 0:
            self.sell(size=abs(size))
        else:
            self.buy(size=abs(size))

