    params = (('fast_ma_period', 14),
              ('slow_ma_period', 50),
              ('risk_ratio', 1.0),
              ('buy_percentage', 0.9),
              ('sell_percentage', 0.2))

    def __init__(self):

        self.fast_ma = bt.ind.SMA(period=self.params.fast_ma_period)
        self.slow_ma = bt.ind.SMA(period=self.params.slow_ma_period)
        self.short_sma = bt.ind.SMA(period=20)
        self.mid_sma = bt.ind.SMA(period=30)
        self.long_sma = bt.ind.SMA(period=50)
        self signal = 0.0
        self.ratio = self.params.risk_ratio
        self.buy_pct = 2
        self.sell_pct = 3

    def next(self):

        if not self.position:

            if self.fast_ma > self.slow_ma and self.slow_ma > self.short_sma and self.slow_ma < self.mid_sma and self.slow_ma > self.long_sma:
                self.signal = 1
            elif self.fast_ma < self.slow_ma and self.slow_ma < self.short_sma and self.slow_ma > self.mid_sma and self.slow_ma < self.long_sma:
                self.signal = -1
            else:
                self.signal = 0

        else:
            self.ratio = self.params.risk_ratio
            self.buy_pct = 2
            self.sell_pct = 3
            if self.signal == 1:
                if self.short_sma > self.mid_sma:
                    self.signal = 0
            elif self.signal == -1:
                if self.short_sma < self.mid_sma:
                    self.signal = 0

        if self.signal == 1:
            if self.short_sma > self.mid_sma:
                self.position.close()
                self.buy()
        elif self.signal == -1:
            if self.short_sma < self.mid_sma:
                self.position.close()
                self.sell()
        elif self.signal:
            return

    def notify_buy(self):
        self.order_target_percent(target=self.params.buy_percentage)

    def notify_sell(self):
        self.order_target_percent(target=self.params.sell_percentage)

