class Strategy(bt.Strategy):
    params = (('fast_ma', 20), ('slow_ma', 50),
              ('threshold', 0.05), ('cash', 10000), ('risk_reward', 2))

    def __init__(self):
        self.fast_ma = bt.ind.SMA(period=self.params.fast_ma)
        self.slow_ma = bt.ind.SMA(period=self.params.slow_ma)

        self.close_price = bt.ind.Close

    def next(self):
        if not self.position:
            if self.fast_ma < self.slow_ma:
                self.buy()
        else:
            if self.close_price > self.params.threshold * self.close_price:
                self.order_target_percent(target=self.params.risk_reward)

class Strategy(bt.Strategy):
    def __init__(self):
        self.dataclose = self.data-close
        self.rsi = bt.indicators.RSI(self.data, period=14)
        self.boll = bt.indicators.BBands(self.data, period=20, devfactor=2)
        self.ema = bt.indicators.EMA(self.data, period=50)
        self.sma = bt.indicators.SMA(self.data, period=200)

    def next(self):
        if not self.barnum:
            return

        if self.rsi > 70 and self.close > self.boll.lines.top:
            self.buy()

        elif self.rsi < 30 and self.close < self.boll.lines.bot:
            self.sell()

        elif self.close > self.ema:
            self.close()

        elif self.ema > self.sma:
            self.order_target_percent(target_percent=self.position.size / self.broker.getcash())

class Strategy(bt.Strategy):
    params = (('fast_ma_period', 20),
              ('slow_ma_period', 50),
              ('short-loving', 0.2),
              ('cash_fraction', 0.7))

    def __init__(self):
        self.fast_ma = bt.ind.SMA(period=self.params.fast_ma_period)
        self.slow_ma = bt.ind.SMA(period=self.params.slow_ma_period)
        self.cash_fraction = self.params.cash_fraction

    def next(self):
        if not self.position:
            if self.fast_ma > self.slow_ma:
                self.buy(size=self.size)
        else:
            size = self.size
            if self.fast_ma < self.slow_ma:
                self.close(size=self.size)

    def notify_trade(self, trade):
        if tradeClosure:
            cash_fraction = self.size / trade.value
            if cash_fraction < self.params.cash_fraction:
                return
        super().notify_trade(trade)

class Strategy(bt.Strategy):
    params = (('fast_ma_len', 20), ('slow_ma_len', 50), ('rsi_period', 14), ('rsi_overbought', 70), ('rsi_oversold', 30), ('stake', 0.1))

    def __init__(self):
        self.addminperiod(max(self.params.fast_ma_len, self.params.slow_ma_len, self.params.rsi_period))
        self.addxecutioninfo()

        self.fast_ma = bt.indicators.SMA(period=self.params.fast_ma_len)
        self.slow_ma = bt.indicators.SMA(period=self.params.slow_ma_len)
        self.rsi = bt.indicators.RSI(self.data.close, period=self.params.rsi_period)
        self.data Close = self.data.addinfo(close=True).data

    def next(self):
        self.direct_close = self.data.close

        if self.data Close > self.fast_ma and not self.in_position:
            self.order_target_percent(target=self.params.stake, order neben.)

        elif self.data Close < self.fast_ma and self.in_position:
            self.close()

        elif self.rsi < self.params.rsi_oversold and self.in_position:
            self.order_target_percent(target=self.params.stake, order neben.)

        elif self.rsi > self.params.rsi_overbought and not self.in_position:
            self.order_target_percent(target=self.params.stake, order neben.)

