class Strategy(bt.Strategy):
    params = (('long_window', 20), ('sh_long_window', 50), ('stop_loss', 5))

    def __init__(self):
        self.dataclose = self.data.close
        self.shift = self.dataclose.resample('D').mean()

        self.long_window = self.p.long_window
        self.short_long_window = self.p.sh_long_window
        self.stop_loss = self.p.stop_loss

        self.long_mom = self.short_long_window - self.long_window
        self.long_signal = bt.indicators.SMA(period=self.long_window)
        self.short_long_signal = bt.indicators.SMA(period=self.short_long_window)
        self.stop_order = bt.indicators.SMA(period=self.stop_loss)

    def next(self):
        if len(self) >= self.long_window:
            if self.short_long_signal.lag(1) > self.short_long_signal:
                self.order_target_percent(target=self.short_long_signal * 1.01)

            if self.short_long_signal < self.short_long_signal.lag(1):
                self.order_target_percent(target=self.short_long_signal * 0.99)

            if self.stop_order < self.stop_order.lag(1) and self.dataclose < self.stop_order:
                self.close()

            if self.stop_order > self.stop_order.lag(1) and self.dataclose > self.stop_order:
                self.buy()

class Strategy(bt.Strategy):
    params = (('fast', 20), ('slow', 40), ('short_window', 5), ('long_window', 15),
              ('status', 'Neutral'),)

    def __init__(self):
        fast_ma = bt.ind.SMA(period=self.params.fast, plot=False)
        slow_ma = bt.ind.SMA(period=self.params.slow, plot=False)
        self.short_window = bt.ind.SMA(period=self.params.short_window, plot=False)
        self.long_window = bt.ind.SMA(period=self.params.long_window, plot=False)
        rule = fast_ma >= slow_ma
        trigger = bt.ind.CrossOver(rule, rule, plot=False)
        self.position_status = self.PositionStatus
        self.add_child(trigger, name='trigger')
        self.position = self.position

    def PositionStatus(self):
        if self.position:
            if self.position.size > 0:
                return 'Long'
            else:
                return 'Short'
        else:
            return 'Neutral'

    def next(self):
        if not self.position:  # no position
            if self.data.close > self.short_window:
                if self.PositionStatus()!= 'Long':
                    self.order_target_percent(target=1.0, exchange=bt.AlgoTrader())
        elif self.data.close < self.long_window:
            self.close()
        elif self.data.close > self.short_window:
            if self.short_window > self.long_window:
                self.order_target_percent(target=-1.0, exchange=bt.AlgoTrader())
            else:
                self.order_target_percent(target=1.0, exchange=bt.AlgoTrader())

    def notify_trade(self, trade):
        if trade.status == trade.Done:
            print(f'Buy/E Sell price={self.data.close}{tradeClosureMethod}')

    def close(self):
        if self.position:
            self.log('Closed. Amount={}'.format(self.position.size))

class Strategy(bt.Strategy):
    params = (
        ('short_window', 20),
        ('long_window', 50),
        ('risk', 0.5),
    )

    def __init__(self):
        self.dataclose = self.datas[0].close
        self.sma_short = bt.indicators.SMA(period=self.p.short_window)
        self.sma_long = bt.indicators.SMA(period=self.p.long_window)
        self.ratio = self.sma_short / self.sma_long

    def next(self):
        if not self.position:
            if self.ratio < 1:
                if self.ratio < 0.9:
                    if self.dataclose < self.sma_short:
                        if self.p.risk * self.get_broker().cash > self.broker.get_value():
                            self.buy()
        else:
            if self.ratio >= 1:
                if self.ratio > 1.1:
                    if self.dataclose > self.sma_long:
                        self.close()

