        self.fast_ma = bt.indicators.SMA(period=self.params.fast_ma_periods)
        self.slow_ma = bt.indicators.SMA(period=self.params.slow_ma_periods)
        self.risk = self.params.risk
        self.cash_allocation = self.params.cash_allocation
        self.size = self.broker.getvalue() * self.cash_allocation

    def next(self):
        if not self.position:
            if self.fast_ma > self.slow_ma:
                self.buy(size=max(int(self.size / self.slow_ma), 1))
                self.size = max(int(self.size - (self.slow_ma * self.risk)), 1)
