            self.order = self.order_target_percent(target=0.3)
            self.sell()

        if self.mom.lines.atr > self.slow_ma:
            percentage = (self.data.close - self.slow_ma) / self.slow_ma
            is_momentum = False
            p = 0
            for i in range(self.params.momentum_window):
                next_price = self.data.close[i + 1] if i + 1 < len(self.data) else self.fast_ma.lines.sma[0]
                mom = next_price - self.data.close[i]
                if mom > 0:
                    is_momentum = True
                else:
                    is_momentum = False
                    break
                p += mom
            if is_momentum and p > 0 and percentage > self.params.momentum_ceiling:
                if self.order:
                    self.close()
                self.order = self.order_target_percent(target=0.5)
                self.buy()
            elif is_momentum and p < 0 and abs(percentage) > self.params.momentum_ceiling:
                if self.order:
                    self.close()
                self.order = self.order_target_percent(target=0.5)
                self.sell()

