class Strategy(bt.Strategy):
    params = (('buy_threshold', 10), ('sell_threshold', -20), ('target_fraction', 0.05))

    def __init__(self):
        self.data_close = self.data.close
        self.data_short_smma = bt.ind.SimpleMovingAverage(self.data_close, period=10)
        self.data_long_smma = bt.ind.SimpleMovingAverage(self.data_close, period=20)
        self说的短均线和长均线差值的移动平均
        self.data_diff_smma = bt.ind.SimpleMovingAverage((self.data_long_smma - self.data_short_smma).abs(), period=10)

    def next(self):
        if not self.in_position():
            if self.data_close > self.data_short_smma and self.data_close > self.data_long_smma:
                self.order_target_percent(target=self.params.target_fraction)
        elif self.data_close < self.data_short_smma and self.data_diff_smma < self.params.buy_threshold:
            self.close()
        elif self.data_close > self.data_long_smma and self.data_diff_smma > self.params.sell_threshold:
            self.close()

    def in_position(self):
        return not self.position.size.__bool__()

class Strategy(bt.Strategy):
    def __init__(self):
        self.dataclose = self.data.close
        self.rsi = bt.indicators.RSI(self.dataclose, period=14)
        self.renyi = bt.indicators.RSI(self.data.close, period=25)

    def next(self):
        if self.rsi > 70 or self.renyi < 30:
            self.close()
            return

        cash = self.broker.getvalue()
        position = self.position.size
        value = position * self.dataclose
        desired = portfolio_size = cash / 2

        excess = desired - value
        if excess > 0:
            order = self.order_target_percent(data = self.data, target = 0.5)
        else:
            order = self.order_target_percent(data = self.data, target = 0.25)

