    def __init__(self):
        self.dataclose = self.data.close
        self.short = bt.indicators.SMA(period=self.params.short_window)
        self.long = bt.indicators.SMA(period=self.params.long_window)
        self.buying = self.data.close > self.short
        self.selling = self.data.close < self.long

    def next(self):
        if self.buying[0] and self.position.size == 0:
            self.buy()
        elif self.selling[0] and self.position.size > 0:
            self.close()
        elif self.buying[0] and self.position.size > 0:
            self.close()
            self.buy()
        if self.data.close > self.long and not self.position.size == 0:
            self.sell()
            self.order_target_percent(target=self.params.cash_ratio)

