class Strategy(bt.Strategy):
    params = (('fast_ma_window', 10), ('slow_ma_window', 50), ('signal_window', 10), ('cash_percent', 0.02), ('threshold', 3))

    def __init__(self):
        self.fast_ma = bt.indicators.SMA(period=self.params.fast_ma_window)
        self.slow_ma = bt.indicators.SMA(period=self.params.slow_ma_window)
        self.signal = bt.indicators.SMA(period=self.params.signal_window)

    def next(self):
        if not self.position:
            if self.fast_ma > self.slow_ma and self.slow_ma > self.signal:
                self.order_target_percent(target = self.params.cash_percent)
            elif self.fast_ma < self.slow_ma and self.slow_ma > self.signal:
                self.sell()

            elif self.fast_ma > self.slow_ma and self.fast_ma - self.slow_ma > self.params.threshold:
                self.order_target_percent(target = self.params.cash_percent)

            elif self.fast_ma < self.slow_ma and self.slow_ma - self.fast_ma > self.params.threshold:
                self.sell()

            else:
                self.close()

        else:
            if self.fast_ma < self.slow_ma and self.slow_ma - self.fast_ma > self.params.threshold:
                self.order_target_percent(target = self.params.cash_percent)

            elif self.fast_ma > self.slow_ma and self.speed(self.fast_ma - self.slow_ma) < self.params.threshold:
                self.sell()

            else:
                self.close()

