class Strategy(bt.Strategy):
    params = (('maperiod', 20),)

    def __init__(self):
        self.dataclose = self.data.close
        self.rsi = bt.indicators.RSI(self.dataclose, period=14)
        self.momentum = bt.indicators.Momentum(self.dataclose, period=20)
        self.sma = bt.indicators.SMA(self.dataclose, period=20)
        self.macd = bt.indicators.MACD(self.dataclose, fastmas period=12, slowmas=26, signalperiod=9)

    def next(self):

        if not self.position:
            if self.rsi < 30 and self.momentum > 0 and self.close > self.sma:
                self.order_target_percent(target=0.9)
            elif self.macd > 0:
                self.order_target_percent(target=0.5)

        else:
            stop_conditions = [
                self.close < (self.sma - 5),  # going against the trend
                self.rsi < 45,  # Below 45, suggested to close part or all of our position
                self.close < self.sma * 0.95,  # going against the current momentum for a large portion
            ]
            for condition in stop_conditions:
                if condition:
                    self.close()
        if self.position and abs(self.position.size) < 0.05:
            self.close()

class Strategy(bt.Strategy):
    params = (('fast_window', 20), ('slow_window', 50), ('risk_percent', 0.02))

    def __init__(self):
        self.fast_ma = bt.ind.SMA(period=self.params.fast_window)
        self.slow_ma = bt.ind.SMA(period=self.params.slow_window)
        self.crossover = bt.ind.CrossOver(self.fast_ma, self.slow_ma)
        self.hbar = bt.indicators.HLineSeries()

    def next(self):
        if self.crossover > 0 and self.position.size == 0:
            self.buy()
        elif self.crossover < 0 and self.position.size > 0:
            self.close()

            # if the price drops, we'll try to buy back
            if self.GetData() - self.datas[0].low[-1] > (selfGetData() - self.datas[0].close[-1]) * self.params.risk_percent:
                self.buy()
            else:
                self.order_target_percent(target= (self.GetData() - self.datas[0].low[-1]) / (selfGetData() - self.datas[0].close[-1]))

        else:
            self.order_target_percent(target=self.params.risk_percent)

