        self.boll = btind.BollingerBands(
            period=self.p.short_window,
            dev=self.p.r_use,
            onmultiple=False,
            plot=False
        )
        self.addindicator(self.boll)

    def next(self):
        if self.data.close[0] > self.boll.bband[0]:
            if self.position.size == 0:
                self.order_target_percent(target=1.0)
        elif self.data.close[0] < self.boll.band[0]:
            if self.position.size > 0:
                self.order_target_percent(target=0.0)

    def addindicator(self, indicator):
        self.boll_bband = indicator.bband
        self.boll_band = indicator.band

class Strategy(bt.Strategy):
    params = (('rsi_length', 14), ('bb_length', 20), ('ticker', "NVDA"), ('cash_proportion', 0.02))

    def __init__(self):
        if not self.p.ticker or self.p.ticker!= self.dataUIColor:
            raise ValueError(f'Ticker must be defined as {self.p.ticker} in params.')
        self.data_close = self.data.close
        self.boll = bt.indicators.BBANDS(self.data_close, period=self.p.bb_length, plot=False)
        self.rsi = bt.indicators.RSI(self.data_close, period=self.p.rsi_length)

    def next(self):
        if not self.position:
            if self.rsi < 30 and self.data_close[0] > self.boll.lines.lower:
                self.buy()
        else:
            if self.rsi > 70:
                self.close()
            elif self.rsi > 80 and self.rsi > self.rsi[-2] and self.data_close[0] < self.boll.lines.upper:
                self.sell()
            elif self.rsi > 80 or not self.data_close[0] < self.boll.lines.lower or not self.rsi[-2] > self.rsi[-1]:
                if self.pos:
                    self.close()
                else:
                    self.buy()

class Strategy(bt.Strategy):
    params = (('fast_window', 22),
              ('slow_window', 55),
              ('mediate_window', 99),  # The 'long' short period
              ('ind_period', 55), # The slow period
              ('ind_shift', 10), # Shift the slow moving average
              ('LongEntryThreshold', 0.6), # Entry threshold for LONG positions
              ('ShortEntryThreshold', -0.6), # Entry threshold for SHOT positions
              ('LongClose', 0.025), # Stop loss for long positions
              ('ShortClose', -0.025), # Stop loss for short positions
              )

    def __init__(self):
        self.fast_ma = bt.ind.SMA(period=self.params.fast_window)
        self.slow_ma = bt.ind.SMA(period=self.params.slow_window)
        self.med_ma = bt.ind.SMA(period=self.params.mediate_window)
        self.ind = bt.ind.SMA(period=self.params.ind_period)
        self.average = self.ind * self.params.ind_shift
        self.rsi = bt.ind.RSI(period=self.params.ind_period)
        self.rsi_average = self.rsi * self.params.ind_shift
        self.trailing_stop_long = self.data.low * self.params.LongClose
        self.trailing_stop_short = self.data.high * self.params.ShortClose

    def next(self):
        if self.get_position().size == 0:
            if (self.fast_ma > self.slow_ma) and (self.rsi_average < -30):
                self.buy()
            elif (self.fast_ma < self.slow_ma) and (self.rsi_average > 30):
                self.sell()
        else:
            if self.get_position().size > 0:
                if self.data.close > self.ind.close and self-med_ma < self-fast_ma: self.close(symbol='NVDA')
                if self.data.high < self.trailing_stop_long: self.close()
            else:
                if self.data.close < self.ind.close and self-med_ma > self-fast_ma: self.close(symbol='NVDA')
                if self.data.low > self.trailing_stop_short: self.close()

