        self.sma_fast = bt.indicators.SMA(period=self.params.short_window)
        self.sma_slow = bt.indicators.SMA(period=self.params.long_window)
        self.SMA toujours = bt.indicators.SMA(period=self.params.moving_avg)

        self.rsi = bt.indicators.RSI(self.dataclose, period=14)

        self signals = bt.indicators.TrendPhasePolicy(outputsignal=False, lags=[self.params.short_window, self.params.long_window])

        self.buy_target = self.order.target_percent()
        self.sell_target = 1 - self.buy_target

    def next(self):
        if self.signals == 'Exit':
            if self.position:
                self.close()
        elif self.signals == 'Long' or self.rsi > 60:
            if not self.position:
                self.buy()
                self.order_target_percent(target=self.params.target_alloc)
        elif self.signals == 'Short' or self.rsi < 40:
            if not self.position:
                self.sell()
                self.order_target_percent(target=self.params.sell_target)

