    params = (('fast_ma_len', 8),
              ('slow_ma_len', 21),
              ('fast_ma_mult', 1.08),
              ('risk_limit', 0.02),
              ('cash_limit', 0.5),)

    def __init__(self):
        self.short_df = self.data
        self.fast_ma = bt.talib.SMA(self.short_df, period=self.params.fast_ma_len)
        self.slow_ma = bt.talib.SMA(self.short_df, period=self.params.slow_ma_len)
        self.rsi = bt.talib.RSI(self.short_df)
        self.cash_limit = self.params.cash_limit

    def next(self):
        if not self.position:
            poscash = self.callsize_c((self.broker.get_cash() * self.cash_limit))
            if self.close > self.params.fast_ma and self.close > self.params.fast_ma_mult * self.params.slow_ma and self.rsi > 50:
                self.order_target_percent(target=poscash)
        else:
            if self.close < self.params.fast_ma_mult * self.params.slow_ma or self.rsi < 50:
                self.close()

    def callsize_c(self, data):
        while self.broker.get_cash() * self.cash_limit > data:
            self.size = (self.broker.get_cash() * self.cash_limit) / self.close
            return self.size

