class Strategy(bt.Strategy):
    params = {'fast_ma_length': 10, 'slow_ma_length': 20, 'threshold': 0.01}

    def __init__(self):
        self.fast_ma = bt.indicators.SMA(period=self.p.fast_ma_length)
        self.slow_ma = bt.indicators.SMA(period=self.p.slow_ma_length)

    def next(self):
        if not self.macd():
            return

    def macd(self):
        fast_ma_diff = self.fast_ma - self.slow_ma
        latest_fast_ma_diff = fast_ma_diff[-1]

        if self.p.threshold and self.position and (latest_fast_ma_diff > self.p.threshold or latest_fast_ma_diff < -self.p.threshold):
            self.close()

        if not self.position and latest_fast_ma_diff > self.p.threshold:
            self.buy()
        elif not self.position and latest_fast_ma_diff < -self.p.threshold:
            self.sell()

