class Strategy(bt.Strategy):
    params = (('fast_ma_len', 20), ('slow_ma_len', 50), ('buy_threshold', 0.05), ('sell_threshold', 0.95), ('trading_threshold', 0.01))

    def __init__(self):
        self.fast_ma = bt.ind.SMA(period=self.p.fast_ma_len)
        self.slow_ma = bt.ind.SMA(period=self.p.slow_ma_len)
        self.close_price = self.data.close
        self.rsi = bt.ind.RSI(self.close_price, period=14)
        self.macd = bt.ind.MACD(self.close_price, fastmatype=bt.ind.SMA, period_fast=self.p.fast_ma_len,
                               period_slow=self.p.slow_ma_len, period_signal=9)

    def next(self):
        if not self.position:
            if self.fast_ma > self.slow_ma:
                if open_position(self.close_price)!= (self.data.close + self.p.trading_threshold * self.data.close):
                    self.buy()
        else:
            percent = ((self.data.close + self.p.trading_threshold * self.data.close) - self.close_price.rolling(1).mean()) / self.close_price.rolling(1).mean()
            if percent > self.p.buy_threshold:
                self.sell()
            elif percent < self.p.sell_threshold:
                self.close()
                self.buy()

def open_position(price):
    if price < float('inf'):
        return price + 0.001
    else:
        return price

