        self.risk = self.params.risk

    def next(self):
        if not self.position:
            if self.fast_ma > self.slow_ma:
                self.buy()
        else:
            if self.close < self.fast_ma * (1 - self.risk) or self.close > self.fast_ma * (1 + self.risk):
                self.close()
            elif self.fast_ma < self.slow_ma:
                self.close()
                self.buy()

