        self.sma_fast = bt.indicators.SimpleMovingAverage(self.data, period=self.params.sma_fast)
        self.sma_slow = bt.indicators.SimpleMovingAverage(self.data, period=self.params.sma_slow)
        self.order = None

    def next(self):
        if self.order:
            return

        if self.sma_fast[0] > self.sma_slow[0] and self.sma_fast[-1] <= self.sma_slow[-1]:
            self.order = self.buy()

        elif self.sma_fast[0] < self.sma_slow[0] and self.sma_fast[-1] >= self.sma_slow[-1]:
            self.order = self.sell()

    def notify_order(self, order):
        if order.status in [order.Submitted, order.Accepted]:
            return

        if order.status in [order.Completed]:
            self.order = None

        elif order.status in [order.Canceled, order.Margin, order.Rejected]:
            self.order = None

