class Strategy(bt.Strategy):
    params = (
        ('ma_short', 20),
        ('ma_long', 50),
    )

    def __init__(self):
        self.data_close = self.datas[0].close
        self.short_ma = bt.indicators.SimpleMovingAverage(self.data_close, period=self.params.ma_short)
        self.long_ma = bt.indicators.SimpleMovingAverage(self.data_close, period=self.params.ma_long)
        self.signal = bt.And(bt.CrossOver(self.short_ma, self.long_ma), self.short_ma > self.long_ma)

    def next(self):
        if self.signal[0] == 1:
            self.order_target_percent(target=1)
        elif self.short_ma < self.long_ma:
            self.order_target_percent(target=0)

