class Strategy(bt.Strategy):
    params = (
        ('fast_period', 50),
        ('slow_period', 200),
        ('take_profit_pct', 0.05),
        ('stop_loss_pct', 0.02),
    )

    def __init__(self):
        self.dataclose = self.datas[0].close
        self.order = None
        self.buy_price = None
        self.take_profit_price = None
        self.stop_loss_price = None
        self.fast_ma = bt.indicators.SimpleMovingAverage(self.datas[0], period=self.params.fast_period)
        self.slow_ma = bt.indicators.SimpleMovingAverage(self.datas[0], period=self.params.slow_period)

    def next(self):
        if self.order:
            return

        if not self.position:
            if self.fast_ma[0] > self.slow_ma[0]:
                self.buy_price = self.dataclose[0]
                self.take_profit_price = self.buy_price * (1 + self.params.take_profit_pct)
                self.stop_loss_price = self.buy_price * (1 - self.params.stop_loss_pct)
                self.order = self.buy()
        else:
            if self.dataclose[0] >= self.take_profit_price or self.dataclose[0] <= self.stop_loss_price:
                self.close()
                self.order = None

