class Strategy(bt.Strategy):
    params = (
        ('short_period', 5),
        ('long_period', 30),
    )

    def __init__(self):
        self.data_close = self.datas[0].close
        self.short_mavg = bt.indicators.MovingAverageSimple(self.data_close, period=self.params.short_period)
        self.long_mavg = bt.indicators.MovingAverageSimple(self.data_close, period=self.params.long_period)
        self.order = None

    def next(self):
        if self.order:
            return

        if self.short_mavg > self.long_mavg:
            self.order = self.order_target_percent(target=1.0)
        elif self.short_mavg < self.long_mavg:
            self.order = self.close()

    def notify_order(self, order):
        if order.status in [order.Submitted, order.Accepted]:
            return

        if order.status in [order.Completed, order.Canceled, order.Margin, order.Rejected]:
            self.order = None

