class Strategy(bt.Strategy):
    params = (
        ('period', 20),
        ('threshold', 2.0),
    )

    def __init__(self):
        self.sma = bt.indicators.SimpleMovingAverage(self.data.close, period=self.params.period)
        self.bollinger = bt.indicators.BollingerBands(self.data.close, period=self.params.period)
        self.order = None

    def next(self):
        if self.order:
            return

        if self.data.close > self.bollinger.lines.top:
            self.order = self.sell()

        elif self.data.close < self.bollinger.lines.bot:
            self.order = self.buy()

        elif self.data.close > self.sma and self.position.size == 0:
            self.order = self.order_target_percent(target=1.0)

        elif self.data.close < self.sma and self.position.size > 0:
            self.order = self.close()

